CREATE TABLE IF NOT EXISTS "AreasMonitoradas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nome" varchar(120) NOT NULL,
    "Municipio" varchar(120) NOT NULL,
    "Latitude" numeric(9,6) NOT NULL CHECK ("Latitude" BETWEEN -90 AND 90),
    "Longitude" numeric(9,6) NOT NULL CHECK ("Longitude" BETWEEN -180 AND 180)
);
CREATE TABLE IF NOT EXISTS "Alertas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "AreaMonitoradaId" integer NOT NULL REFERENCES "AreasMonitoradas"("Id") ON DELETE RESTRICT,
    "Titulo" varchar(150) NOT NULL,
    "FonteOrbital" varchar(120) NOT NULL,
    "ReferenciaObservacao" varchar(500) NOT NULL,
    "Status" varchar(20) NOT NULL CHECK ("Status" IN ('aberto','analise','resolvido'))
);
